import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            S = next(iterator)
        except StopIteration:
            break

        groups = 0
        if not S:
            results.append("0")
            continue

        current_char = S[0]
        groups = 1

        for i in range(1, len(S)):
            if S[i] != current_char:
                groups += 1
                current_char = S[i]

        if groups == 1:
            results.append("0")
        else:
            ans = groups // 2
            results.append(str(ans))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
